#include <stdio.h>

#define MAXN 505

char grid[MAXN][MAXN];
int queue_r[MAXN * MAXN];
int queue_c[MAXN * MAXN];

int main() {
    int n, f;
    if (scanf("%d %d", &n, &f) != 2) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%s", grid[i]);
    }

    // Se o ponto inicial puder ser invadido pela lava
    if (grid[0][0] - '0' <= f) {
        int head = 0, tail = 0;
        grid[0][0] = '*';
        queue_r[tail] = 0;
        queue_c[tail] = 0;
        tail++;

        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};

        while (head < tail) {
            int r = queue_r[head];
            int c = queue_c[head];
            head++;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    if (grid[nr][nc] != '*' && (grid[nr][nc] - '0') <= f) {
                        grid[nr][nc] = '*';
                        queue_r[tail] = nr;
                        queue_c[tail] = nc;
                        tail++;
                    }
                }
            }
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
